drop table public.dim_region;CREATE TABLE public.dim_region (  sk_region INTEGER,  id INTEGER,  level VARCHAR(30),  name VARCHAR(100),  macro_id INTEGER,  macro_name VARCHAR(100),  city_id INTEGER,  city_name VARCHAR(100),  region_code VARCHAR(10),  short_region_name VARCHAR(255),  long_region_name VARCHAR(255),  greater_region VARCHAR(100),  dt_created TIMESTAMP WITHOUT TIME ZONE,  dt_updated TIMESTAMP WITHOUT TIME ZONE,  dt_timestamp TIMESTAMP WITHOUT TIME ZONE,  dt_first_property_created TIMESTAMP,  dt_first_booking TIMESTAMP WITHOUT TIME ZONE,  days_from_first_booking INTEGER,  CONSTRAINT dim_region_pkey PRIMARY KEY(sk_region)) ;